update public.espia_cases set code='2A',title='Emprego',configuration='{"id": "employment", "code": "2A", "campaign": "work", "title": "Emprego", "question": "Que oportunidade combina com o que eu sei fazer ou quero aprender?", "agency": "Sedet", "source": "Sedet • Quadro de vagas", "url": "https://sedet.df.gov.br/quadro-de-vagas", "tool": "orgao", "search": "Data do quadro, ocupação, escolaridade, experiência, local, remuneração publicada e candidatura.", "initial": "Um anúncio fictício de auxiliar de comércio pede ensino médio e promete vaga mediante PIX. Falta fonte e procedimento de candidatura.", "other": "Quero aprender a trabalhar com atendimento. Será que meu interesse basta para essa vaga ou preciso conferir outros requisitos?", "facts": ["Quadro fictício: auxiliar de comércio, ensino médio, experiência não exigida, local Setor Horizonte.", "No caso, a candidatura segue o canal do quadro oficial; o anúncio de PIX não comprova vínculo com o serviço. Compare requisitos com suas habilidades.", "Remuneração individual e cargos vagos no Portal da Transparência ajudam a investigar carreiras públicas; não comprovam salário inicial nem concurso aberto."], "limit": "Não se candidatar por LAI; não confundir carreira pública, vaga de emprego e concurso.", "record": "Oportunidade, data, requisitos, o que atende e o que precisa desenvolver; procedimento de candidatura.", "participation": "LAI para informação existente sobre o serviço não localizada; ouvidoria para atendimento real. Candidatura no canal próprio.", "channel": "lai", "deep": "Pesquise uma profissão pública em Servidores → Remuneração e Cargos efetivos. Registre cargo e referência, sem coletar nomes.", "art": "jobs"}'::jsonb where id='employment';
update public.espia_activities set title='Conhecer o problema • Emprego',prompt='Que oportunidade combina com o que a equipe sabe fazer ou quer aprender?',place='square',target='[50, 83]'::jsonb where case_id='employment' and kind='route';
