update public.espia_cases set code='2B',title='Formação profissional',configuration='{"id": "training", "code": "2B", "campaign": "work", "title": "Formação profissional", "question": "O Pró-Jovem Digital pode ajudar na preparação para trabalhar ou empreender?", "agency": "Secretaria da Juventude", "source": "Secretaria da Juventude • Pró-Jovem Digital", "url": "https://juventude.df.gov.br/pro-jovem-digital", "tool": "orgao", "search": "Objetivo, público, áreas, requisitos e orientações atuais de participação.", "initial": "O grupo recebeu uma descrição fictícia de um curso digital, sem data de seleção nem orientações de inscrição.", "other": "Encontrei uma página explicando o Pró-Jovem Digital e já queria me inscrever. Será que essa página confirma uma turma aberta hoje?", "facts": ["Registro fictício: programa de qualificação digital com áreas de interesse para trabalho e empreendedorismo.", "Procure objetivo, público, áreas, requisitos e instruções atuais; leia a fonte real para saber as condições vigentes.", "A descrição de um programa não equivale a uma seleção aberta; o jogo não exige matrícula."], "limit": "Distinguir página do programa e seleção aberta; inscrição segue canal divulgado.", "record": "Objetivo, público, área de interesse, requisitos e informação de inscrição; já é possível saber como participar?", "participation": "LAI para regras ou informações existentes ausentes; ouvidoria para manifestação real. Inscrição no canal próprio.", "channel": "lai", "art": "course"}'::jsonb where id='training';
