update public.espia_activities set title='Abrir • Descrição do programa de formação',prompt='A descrição do programa informa objetivo, público e áreas? Ela também confirma uma seleção aberta agora?',place='park',target='[43, 61]'::jsonb where case_id='training' and kind='board';
