update public.espia_activities set title='Conferir a descoberta • Formação profissional',prompt='Encontramos uma explicação do programa ou uma seleção com data e requisitos atuais? O que ainda falta confirmar?',place='park',target='[57, 69]'::jsonb where case_id='training' and kind='verify';
