update public.espia_activities set title='Preparar o próximo passo • Formação profissional',prompt='A informação publicada resolveu a dúvida? Se falta uma informação existente, escrevam a pergunta; inscrição segue o canal divulgado.',place='park',target='[69, 80]'::jsonb where case_id='training' and kind='channel';
update public.espia_activities set title='Ler o retorno • Formação profissional',prompt='O retorno confirma público, área e condições de participação? Continua faltando uma data de seleção?',place='lab',target='[45, 81]'::jsonb where case_id='training' and kind='response';
