update public.espia_cases set code='2C',title='Remuneração de servidores',configuration='{"id": "pay", "code": "2C", "campaign": "work", "title": "Remuneração de servidores", "question": "O que a remuneração publicada mostra sobre uma profissão pública?", "agency": "Órgão responsável pelos registros de pessoal", "source": "Portal da Transparência • Servidores → Remuneração", "url": "https://www.transparencia.df.gov.br/", "tool": "transparencia", "search": "Cargo, órgão e mês; valores bruto e líquido; comparar registros equivalentes.", "initial": "Um colega viu uma remuneração individual e disse: todo iniciante dessa carreira ganha isso.", "other": "Achei um valor de remuneração de um servidor e pensei que fosse o salário inicial da carreira. O que eu teria de conferir antes de dizer isso?", "facts": ["Exemplo fictício sem nomes e sem valores reais: dois registros de um mesmo cargo e mês têm componentes e descontos diferentes.", "Bruto e líquido são medidas diferentes. Compare cargo, órgão, mês e componentes equivalentes.", "Para salário inicial, consulte a tabela remuneratória já disponível em transparência ativa; não crie LAI para obter o que está publicado."], "limit": "Não fixar valores reais no jogo nem coletar nomes. Remuneração individual não comprova salário inicial.", "record": "Cargo, órgão, mês, valores comparados e limites da comparação; sem nomes de servidores.", "participation": "Ouvidoria para dificuldade real de acesso, sugestão de apresentação ou possível inconsistência observada. Consulte a tabela já publicada.", "channel": "ouvidoria", "art": "pay"}'::jsonb where id='pay';
