update public.espia_activities set title='Ler o retorno • Remuneração de servidores',prompt='O retorno explica a remuneração e sua referência? Ele confirma salário inicial ou ainda falta a tabela correspondente?',place='park',target='[45, 81]'::jsonb where case_id='pay' and kind='response';
