update public.espia_cases set code='2D',title='Cargos públicos vagos',configuration='{"id": "vacancies", "code": "2D", "campaign": "work", "title": "Cargos públicos vagos", "question": "Quantos cargos vagos existem numa carreira de interesse e o que isso significa?", "agency": "Órgão responsável pelos registros de pessoal", "source": "Portal da Transparência • Servidores → Cargos efetivos", "url": "https://www.transparencia.df.gov.br/", "tool": "transparencia", "search": "Cargo, referência, ocupados, vagos e total; orientações sobre concursos.", "initial": "No cenário, a carreira fictícia tem cargos vagos. Uma mensagem afirma que as inscrições de concurso já estão abertas.", "other": "Vi cargos vagos na carreira que me interessa e achei que já haveria concurso. Onde encontro um documento que confirme se existe seleção aberta?", "facts": ["Exemplo inteiramente fictício: carreira Horizonte, referência de demonstração, 80 ocupados, 20 vagos, total 100.", "A conta mostra vacância nesse recorte. Não comprova concurso aberto, autorização, nomeação ou previsão de seleção.", "Para verificar seleção, procure edital e documento existente de autorização ou planejamento. Não exija previsão ainda inexistente."], "limit": "Vacância não é edital aberto. Não exigir criação de informação ou previsão inexistente.", "record": "Cargo, órgão ou carreira, referência, ocupados, vagos e total; isso comprova concurso aberto?", "participation": "LAI para documento existente de autorização ou planejamento não encontrado; não exigir previsão de concurso ou nomeação inexistente.", "channel": "lai", "art": "vacancy"}'::jsonb where id='vacancies';
update public.espia_activities set title='Conhecer o problema • Cargos públicos vagos',prompt='Qual carreira pública a equipe quer conhecer e o que pretende descobrir sobre seus cargos?',place='square',target='[50, 83]'::jsonb where case_id='vacancies' and kind='route';
