update public.espia_activities set title='Conferir a descoberta • Cargos públicos vagos',prompt='Os números se referem à mesma carreira e data? Encontramos algum edital ou só a informação de vacância?',place='park',target='[57, 69]'::jsonb where case_id='vacancies' and kind='verify';
