update public.espia_activities set title='Preparar o próximo passo • Cargos públicos vagos',prompt='Já há um documento público que responda à pergunta? Se não foi localizado, escrevam qual informação existente querem consultar.',place='park',target='[69, 80]'::jsonb where case_id='vacancies' and kind='channel';
update public.espia_activities set title='Ler o retorno • Cargos públicos vagos',prompt='A resposta traz um edital ou apenas esclarece o quadro de cargos? O que ainda não pode ser anunciado?',place='lab',target='[45, 81]'::jsonb where case_id='vacancies' and kind='response';
