update public.espia_cases set code='3A',title='Quadra esportiva',configuration='{"id": "court", "code": "3A", "campaign": "territory", "title": "Quadra esportiva", "question": "Podemos usar ou reservar uma quadra na quarta-feira, das 17h às 18h?", "agency": "Administração responsável pelo espaço", "source": "Plano Piloto • Carta de Serviços", "url": "https://planopiloto.df.gov.br/carta-de-servicos-do-plano-piloto-ao-cidadao", "tool": "orgao", "search": "Gestor, uso livre ou reserva, regras e forma de confirmar horário.", "initial": "O grupo quer usar a quadra fictícia na quarta, das 17h às 18h. Não encontrou agenda confirmada.", "other": "Já joguei nessa quadra na quarta às 17h. Isso quer dizer que posso garantir o mesmo horário para o encontro da equipe na próxima semana?", "facts": ["Observação fictícia: quadra pública, horário pretendido quarta-feira das 17h às 18h.", "Verifique gestor, regra de uso livre ou reserva e forma de confirmar. Não presumir agenda online.", "A página indicada apresentou falha na revisão. Registre a busca e a lacuna; a rota real depende de página acessível indicada pela Administração."], "limit": "Regra de uso não comprova disponibilidade. Reserva e agenda online não confirmadas.", "record": "Quadra, gestor, regras e o que falta confirmar; em falha da página, registrar busca e lacuna.", "participation": "LAI para regras existentes ausentes; ouvidoria para reparo real, com referência pública e situação observada.", "channel": "lai", "warning": "PENDÊNCIA CGDF: página da Carta de Serviços retornou erro; procedimento de reserva não confirmado. Não simular agenda real.", "art": "court"}'::jsonb where id='court';
update public.espia_activities set title='Conhecer o problema • Quadra esportiva',prompt='A equipe quer usar a quadra na quarta-feira, das 17h às 18h. O que precisa descobrir antes de combinar o encontro?',place='square',target='[50, 83]'::jsonb where case_id='court' and kind='route';
update public.espia_activities set title='Ouvir orientação • Quadra esportiva',prompt='Quem pode explicar as regras de uso e como confirmar o horário pretendido?',place='park',target='[57, 69]'::jsonb where case_id='court' and kind='agent';
