update public.espia_activities set title='Conferir a descoberta • Quadra esportiva',prompt='A fonte confirma uso livre, reserva ou outra regra? Conseguimos confirmar o horário ou a página não permitiu verificar?',place='park',target='[57, 69]'::jsonb where case_id='court' and kind='verify';
