update public.espia_cases set code='3B',title='Lixo e coleta seletiva',configuration='{"id": "waste", "code": "3B", "campaign": "territory", "title": "Lixo e coleta seletiva", "question": "Quando os resíduos são recolhidos e o que deve ser separado?", "agency": "SLU", "source": "SLU • Coleta DF e mapas", "url": "https://www.slu.df.gov.br/aplicativo-slu-coleta-df/", "tool": "orgao", "search": "Coletas convencional e seletiva, separação e cronograma de ponto público de referência.", "initial": "No ponto público fictício há sacos misturados e ninguém sabe o dia da coleta seletiva.", "other": "Eu vi um caminhão passando ontem, mas não sei se era coleta convencional ou seletiva. Como descubro o dia e a separação certa?", "facts": ["Cronograma fictício: convencional segunda, quarta e sexta; seletiva terça. Não é agenda de local real.", "Separe conforme a orientação oficial e consulte o tipo de coleta e cronograma para um ponto público.", "Despesa ou contrato revela finalidade, área atendida, período e valor; não comprova passagem do caminhão num endereço."], "limit": "Contrato não comprova coleta num ponto; diferenciar convencional e seletiva.", "record": "Tipo, cronograma, separação e próximo passo; em aprofundamento, finalidade, período e alcance financeiro.", "participation": "LAI para cronograma existente ausente; ouvidoria para falha real ou solicitação pertinente, com local e data.", "channel": "ouvidoria", "deep": "Busque despesa ou contrato de coleta no Portal da Transparência. Leia finalidade, área, período e valor sem inferir execução local.", "art": "waste"}'::jsonb where id='waste';
update public.espia_activities set title='Conhecer o problema • Lixo e coleta seletiva',prompt='Que dúvida sobre o lixo e a coleta neste ponto público a equipe vai investigar?',place='square',target='[50, 83]'::jsonb where case_id='waste' and kind='route';
update public.espia_activities set title='Ouvir orientação • Lixo e coleta seletiva',prompt='Como distinguir a coleta convencional da seletiva antes de procurar o cronograma?',place='park',target='[57, 69]'::jsonb where case_id='waste' and kind='agent';
update public.espia_activities set title='Abrir • Cronograma e separação de resíduos',prompt='No registro fictício, quais dias correspondem à coleta convencional e qual à seletiva? O que precisa ser separado?',place='alameda',target='[43, 61]'::jsonb where case_id='waste' and kind='board';
