update public.espia_cases set code='3C',title='Relatórios da PMDF',configuration='{"id": "police", "code": "3C", "campaign": "territory", "title": "Relatórios da PMDF", "question": "O que podemos descobrir sobre a atuação da Polícia Militar em um mês?", "agency": "PMDF • divulgação dos relatórios", "source": "Dados Abertos DF • Relatórios mensais de produtividade de 2026 / PMDF", "url": "https://dados.df.gov.br/pt/dataset#/relatorios-mensais-de-produtividade-de-2026-pmdf", "tool": "dadosabertos", "search": "Escolher um relatório de 2026 e um indicador efetivamente disponível; definição, unidade, período e abrangência.", "initial": "Uma mensagem diz que mais atendimentos registrados significa necessariamente mais crimes.", "other": "Li que houve mais atendimentos registrados e alguém disse que isso prova mais crimes. O que esse indicador mede de verdade?", "facts": ["Exercício fictício sem campos ou números atribuídos ao relatório real: escolha o indicador somente depois de abrir e ler o arquivo.", "Registre título, mês/ano, indicador, definição, unidade e abrangência. Comparar dois meses é opcional e exige recortes equivalentes.", "Produtividade policial não equivale ao total de crimes e não prova aumento ou redução da violência. Um PDF público não é necessariamente dado estruturado reutilizável."], "limit": "O relatório descreve um período, não uma situação em tempo real. Participa DF não substitui emergência nem registro policial.", "record": "Título, mês/ano, indicador, definição, valor e unidade efetivamente encontrados; uma descoberta e uma pergunta sem resposta.", "participation": "LAI para informação existente necessária à compreensão e não localizada; ouvidoria para sugestão de divulgação. Não usar para registro policial.", "channel": "lai", "warning": "PENDÊNCIA CGDF: catálogo identificado; acesso ao arquivo na interface nova não concluído. Não inventar campos nem valores.", "art": "police"}'::jsonb where id='police';
