update public.espia_cases set code='4A',title='Acesso à UBS',configuration='{"id": "ubs", "code": "4A", "campaign": "health", "title": "Acesso à UBS", "question": "Como descobrir onde procurar uma UBS e quais serviços ela oferece?", "agency": "SES-DF", "source": "InfoSaúde • Busca Saúde UBS", "url": "https://info.saude.df.gov.br/busca-saude-ubs/", "tool": "infosaude", "search": "Orientações de acesso, identificação do serviço e unidade para referência pública da Região Administrativa.", "initial": "Uma pessoa fictícia quer saber onde buscar orientação de saúde na Região Administrativa, sem expor história clínica.", "other": "A UBS fica perto da escola, então pensei que qualquer pessoa teria atendimento imediato ali. Como descubro o serviço e o acesso correto?", "facts": ["Use um ponto público da Região Administrativa como referência; nunca registre endereço residencial do estudante.", "Leia orientações dos serviços das UBS e use o mapa de busca para identificar a referência exibida.", "Unidade, localização e orientação de acesso não garantem vaga nem atendimento imediato; confirme o que falta com o serviço."], "limit": "Não pedir consulta por LAI nem anexar dados clínicos.", "record": "Unidade, serviço, referência pública, orientação de acesso e dúvida restante.", "participation": "LAI para informação pública existente sobre funcionamento ausente; ouvidoria para situação real do serviço. Consulta médica segue o serviço.", "channel": "lai", "art": "ubs"}'::jsonb where id='ubs';
