update public.espia_cases set code='4B',title='Vacinação',configuration='{"id": "vaccination", "code": "4B", "campaign": "health", "title": "Vacinação", "question": "Perder o cartão de vacinação impede procurar uma sala de vacina?", "agency": "SES-DF", "source": "SES • Locais de vacinação", "url": "https://www.saude.df.gov.br/locais-de-vacinacao", "tool": "orgao", "search": "Orientações sobre perda do cartão, documentos e locais de vacinação; onde pedir orientação à equipe de saúde.", "initial": "No caso fictício, alguém perdeu o cartão e acredita que não pode procurar a sala de vacina.", "other": "Perdi meu cartão e não sei quais vacinas preciso tomar. Onde posso me informar? Um colega disse que, sem o cartão, nem posso procurar a sala de vacina. Será que essa informação está correta?", "facts": ["Na simulação, a equipe investiga uma regra de acesso ao serviço, sem consultar dados pessoais ou clínicos.", "Consulte a publicação atual sobre documentos, ausência do cartão e locais; registre a orientação que responde à pergunta.", "O jogo não define vacina individual, não avalia situação vacinal e não pede cartão de vacinação."], "limit": "Dúvidas clínicas vão ao serviço de saúde. Não anexar cartão de vacina.", "record": "Orientação que responde à pergunta e próximo passo; fonte e publicação atual, sem cartão ou dados de saúde.", "participation": "LAI para informação pública de acesso ausente; ouvidoria para problema real. Dúvida clínica deve ser orientada pelo serviço.", "channel": "lai", "extra": {"label": "SES • Vacinação de rotina e calendário", "url": "https://www.saude.df.gov.br/vacinacao-de-rotina"}, "art": "vaccine"}'::jsonb where id='vaccination';
