update public.espia_cases set code='4C',title='Dengue',configuration='{"id": "dengue", "code": "4C", "campaign": "health", "title": "Dengue", "question": "Como buscar orientação sobre água parada na Região Administrativa e acompanhar informações de dengue?", "agency": "SES-DF • Vigilância Ambiental", "source": "SES • Vigilância Ambiental", "url": "https://www.saude.df.gov.br/servicos-dival", "tool": "orgao", "search": "Orientação preventiva, canal para possível criadouro e indicador pertinente no InfoSaúde.", "initial": "Há água parada no recipiente fictício. Um colega afirma que isso confirma foco e origem dos casos da Região Administrativa.", "other": "Vi água nesse recipiente e ouvi que ele seria a origem dos casos de dengue da Região Administrativa. Só olhar a água permite afirmar isso?", "facts": ["Observação fictícia: água acumulada; não é foco confirmado nem prova de transmissão.", "Procure orientações e canal da Vigilância Ambiental para situação observável; não entre em terreno ou manuseie resíduos.", "No painel real, compare a mesma medida em recortes equivalentes. Indicador regional não confirma foco num endereço."], "limit": "Não inventar foco confirmado nem atribuir causalidade ao terreno.", "record": "Orientação preventiva, canal e situação observável; se usar painel: indicador, período e conclusão limitada.", "participation": "Ouvidoria para avaliação ou providência real; LAI para informação pública existente não localizada.", "channel": "ouvidoria", "extra": {"label": "InfoSaúde • Dengue", "url": "https://info.saude.df.gov.br/sala-de-situacao/painel-infosaude-dengue/"}, "art": "water"}'::jsonb where id='dengue';
