update public.espia_cases set code='4D',title='Vigilância sanitária',configuration='{"id": "sanitary", "code": "4D", "campaign": "health", "title": "Vigilância sanitária", "question": "Como comunicar possível falha de higiene no local onde compramos lanche?", "agency": "SES-DF • Vigilância Sanitária", "source": "SES • Vigilância Sanitária", "url": "https://www.saude.df.gov.br/divisa", "tool": "orgao", "search": "Atribuições e canais dos núcleos de inspeção; distinguir observação de infração a apurar.", "initial": "Na lanchonete fictícia, o grupo observa alimento exposto e quer afirmar que houve infração.", "other": "Vi alimento exposto na lanchonete e já ia dizer que houve uma infração. Posso afirmar isso ou preciso descrever o que vi para a fiscalização?", "facts": ["Observação fictícia: alimento exposto, local público e data de referência. Não identifica pessoa ou estabelecimento real.", "Consulte atribuições e contatos dos núcleos de inspeção para localizar o canal pertinente.", "Redija relato objetivo da situação observada; a fiscalização apura eventual infração. Sem expor pessoas nem dados clínicos."], "limit": "Não publicar acusações; fato observado não equivale a infração confirmada.", "record": "Situação, referência pública, data, canal e relação com fiscalização; sem expor pessoas.", "participation": "Ouvidoria para relato real objetivo e revisado; LAI para orientação ou documento existente não localizado.", "channel": "ouvidoria", "art": "food"}'::jsonb where id='sanitary';
